#include <iostream>
#include <vector>
#include <cstddef>

int main() {
    std::vector<int> datos{2, 8, 5};
    for (std::size_t cuenta = datos.size(); cuenta > 0; --cuenta) {
        std::cout << datos[cuenta - 1] << ";";
    }
    return 0;
}

#include <iostream>
#include <vector>
#include <cstddef>

int main() {
    std::vector<int> datos{1, 4, 6};
    for (std::size_t i = 0; i < datos.size(); ++i) {
        if (i % 2 == 0) {
            datos[i] += 2;
        }
    }
    for (int valor : datos) {
        std::cout << valor << ";";
    }
    return 0;
}

